import pandas as pd
import numpy as np

# Load the Crime data for 33 London boroughs into a pandas DataFrame
crime_data = pd.read_csv('getisord_2023_crime.csv')

# Load the adjacency data for 33 London boroughs into a pandas DataFrame
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Check for missing values and handle them by dropping the row with the missing value
crime_data = crime_data.dropna()

# Calculate the number of data points used in the analysis
data_points_used = len(crime_data)

# Print the number of data points used in the analysis
print(f"data_points_used = {data_points_used}")

# Create a dictionary to store the neighbors of each borough
neighbors = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Calculate the combined local areas for each borough
combined_crime_values = {}
for borough in crime_data['borough']:
    combined_crime_value = crime_data.loc[crime_data['borough'] == borough, 'Crime_value'].values[0]
    for neighbor in neighbors[borough]:
        combined_crime_value += crime_data.loc[crime_data['borough'] == neighbor, 'Crime_value'].values[0]
    combined_crime_values[borough] = combined_crime_value

# Calculate the citywide average Crime value
citywide_average = crime_data['Crime_value'].mean()

# Calculate the standard deviation of the Crime values
std_dev = crime_data['Crime_value'].std()

# Calculate the z-scores for each combined local area
z_scores = {}
for borough, combined_crime_value in combined_crime_values.items():
    z_score = (combined_crime_value - citywide_average) / std_dev
    z_scores[borough] = z_score

# Identify hot and cold spots using the z-scores
hot_spots = {}
cold_spots = {}
for borough, z_score in z_scores.items():
    if np.abs(z_score) > 1.96:  # 95% confidence
        if z_score > 0:
            hot_spots[borough] = z_score
        else:
            cold_spots[borough] = z_score

# Print the list of boroughs that are statistically significant hot or cold spots
results = []
for borough in hot_spots:
    results.append(f"{borough} (HOT, Gi*={hot_spots[borough]}, gi_value={hot_spots[borough]})")
for borough in cold_spots:
    results.append(f"{borough} (COLD, Gi*={cold_spots[borough]}, gi_value={cold_spots[borough]})")

# Print the final answer
if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")

import pandas as pd
import numpy as np

# Load data
crime_data = pd.read_csv('chunks_csv/getisord/getisord_2023_crime.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
crime_data = crime_data.dropna(subset=['Crime_value'])

# Calculate combined total of Crime_values with neighbors
neighbor_crime_values = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighbor_crime_values:
        neighbor_crime_values[borough] = []
    if neighbor not in neighbor_crime_values:
        neighbor_crime_values[neighbor] = []
    neighbor_crime_values[borough].append(crime_data.loc[crime_data['borough'] == neighbor, 'Crime_value'].values[0])
    neighbor_crime_values[neighbor].append(crime_data.loc[crime_data['borough'] == borough, 'Crime_value'].values[0])

for borough, neighbors in neighbor_crime_values.items():
    if len(neighbors) > 0:
        neighbor_crime_values[borough] = np.mean(neighbors)

# Calculate Getis-Ord Gi*
citywide_average = crime_data['Crime_value'].mean()
gi_values = {}
for index, row in crime_data.iterrows():
    borough = row['borough']
    neighbors = neighbor_crime_values[borough]
    if np.isnan(neighbors):
        neighbors = crime_data.loc[crime_data['borough'] == borough, 'Crime_value'].values[0]
    gi_values[borough] = (neighbors - citywide_average) / citywide_average

# Calculate z-score
z_scores = {}
for borough, gi in gi_values.items():
    z_scores[borough] = np.abs(gi) / np.sqrt((1 / len(crime_data)) + (np.sum(crime_data['Crime_value'] != crime_data['Crime_value']) / len(crime_data)))

# Identify hot/cold spots
hot_cold_spots = {}
for borough, z in z_scores.items():
    if z > 1.96 or z < -1.96:
        hot_cold_spots[borough] = 'HOT' if z > 1.96 else 'COLD'

# Print results
data_points_used = len(crime_data)
results = []
for borough, spot in hot_cold_spots.items():
    results.append(f"{borough} ({spot}, Gi*={gi_values[borough]}, gi_value={gi_values[borough]})")
print(f"data_points_used = {data_points_used}")
if len(results) > 0:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
